export fn intensity_based_segmentation(v:[*]const i64,n:usize)i64{if(n<2 or n>12)return -1;const k=v[0];if(k<0 or k>4 or n<=@as(usize,@intCast(k))+1 or n>@as(usize,@intCast(k))+8)return -1;for(1..n)|j|{if(v[j]<0 or v[j]>255)return -1;}var out:i64=0;var place:i64=1;const kk:usize=@intCast(k);for(kk+1..n)|p|{var label:i64=0;for(0..kk)|i|{if(v[p]>v[i+1])label=@intCast(i+1);}out+=label*place;place*=5;}return out;}
